const fileInput=document.querySelector('#photo-file'),zone=document.querySelector('#drop-zone'),preview=document.querySelector('#photo-preview'),convert=document.querySelector('#convert'),status=document.querySelector('#tool-status'),quality=document.querySelector('#quality'),maxSize=document.querySelector('#max-size'),result=document.querySelector('#result'),download=document.querySelector('#download');
let source=null,sourceFile=null,previewUrl=null,downloadUrl=null,generation=0;
const bytes=n=>n<1024*1024?(n/1024).toFixed(1)+' KB':(n/1024/1024).toFixed(2)+' MB';
function clearDownload(){result.hidden=true;download.removeAttribute('href');if(downloadUrl){URL.revokeObjectURL(downloadUrl);downloadUrl=null}}
function settingsChanged(){clearDownload();if(source)status.textContent='설정을 바꿨어요. 용량 줄이기를 눌러 다시 만들어 주세요.'}
quality.addEventListener('input',()=>{document.querySelector('#quality-value').value=quality.value+'%';settingsChanged()});maxSize.addEventListener('change',settingsChanged);
async function load(file){const current=++generation;clearDownload();source=null;sourceFile=null;convert.disabled=true;document.querySelector('#preview-wrap').hidden=true;if(previewUrl)URL.revokeObjectURL(previewUrl);if(!file){status.textContent='사진을 선택하면 시작할 수 있어요.';return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){status.textContent='JPEG, PNG, WebP 사진을 선택해 주세요. HEIC와 GIF는 지원하지 않습니다.';return}if(file.size>20*1024*1024){status.textContent='20MB 이하의 사진을 선택해 주세요.';return}status.textContent='사진을 불러오고 있어요…';const url=URL.createObjectURL(file);const image=new Image();image.onload=()=>{if(current!==generation){URL.revokeObjectURL(url);return}if(image.naturalWidth*image.naturalHeight>25000000){URL.revokeObjectURL(url);status.textContent='사진이 너무 커요. 2,500만 픽셀 이하의 사진을 선택해 주세요.';return}source=image;sourceFile=file;previewUrl=url;preview.src=url;document.querySelector('#preview-wrap').hidden=false;document.querySelector('#original-info').textContent=`원본 ${bytes(file.size)} · ${image.naturalWidth} × ${image.naturalHeight}px`;convert.disabled=false;status.textContent='사진을 불러왔어요. 크기와 품질을 정한 뒤 시작하세요.'};image.onerror=()=>{URL.revokeObjectURL(url);if(current===generation)status.textContent='사진을 읽을 수 없어요. 다른 사진 파일로 다시 시도해 주세요.'};image.src=url}
fileInput.addEventListener('change',()=>load(fileInput.files[0]));for(const type of ['dragenter','dragover'])zone.addEventListener(type,e=>{e.preventDefault();zone.classList.add('drag')});for(const type of ['dragleave','drop'])zone.addEventListener(type,e=>{e.preventDefault();zone.classList.remove('drag')});zone.addEventListener('drop',e=>load(e.dataTransfer.files[0]));fileInput.addEventListener('focus',()=>zone.style.outline='3px solid #ca9c26');fileInput.addEventListener('blur',()=>zone.style.outline='');
convert.addEventListener('click',async()=>{if(!source)return;const current=generation;convert.disabled=true;status.textContent='사진을 변환하고 있어요…';clearDownload();try{const max=Number(maxSize.value),scale=max?Math.min(1,max/Math.max(source.naturalWidth,source.naturalHeight)):1;const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(source.naturalWidth*scale));canvas.height=Math.max(1,Math.round(source.naturalHeight*scale));const ctx=canvas.getContext('2d');if(!ctx)throw Error('canvas');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(source,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',Number(quality.value)/100));if(current!==generation)return;if(!blob)throw Error('encoding');downloadUrl=URL.createObjectURL(blob);download.href=downloadUrl;download.download=(sourceFile.name.replace(/\.[^.]+$/,'')||'photo')+'-small.jpg';document.querySelector('#result-size').textContent=bytes(blob.size);const change=(1-blob.size/sourceFile.size)*100;document.querySelector('#result-detail').textContent=`${canvas.width} × ${canvas.height}px · ${change>0?change.toFixed(1)+'% 작아졌어요.': '원본보다 작아지지 않았어요. 크기나 품질을 더 낮춰보세요.'}`;result.hidden=false;status.textContent='완료됐어요. 다운로드한 사진의 화질을 확인해 주세요.'}catch{status.textContent='변환하지 못했어요. 더 작은 사진으로 다시 시도해 주세요.'}finally{if(current===generation)convert.disabled=!source}});
window.addEventListener('beforeunload',()=>{if(previewUrl)URL.revokeObjectURL(previewUrl);if(downloadUrl)URL.revokeObjectURL(downloadUrl)});
